<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/billing.php';
$current=tuman_require_role('TEACHER');$db=tuman_database();$students=array_filter(tuman_teacher_students($db,$current['id']),fn($s)=>$s['assignment_status']==='ACTIVE');$v=['assignment_id'=>'','rule_name'=>'','billing_mode'=>'HOURLY','rate'=>'','currency_code'=>'INR','effective_from'=>gmdate('Y-m-d'),'effective_to'=>''];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$assignment=filter_var($v['assignment_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment)throw new InvalidArgumentException('Choose a student.');tuman_create_billing_rule($db,$current['id'],(int)$assignment,$v);header('Location: /Tuman/teacher/billing.php?created=1');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to save the billing rule right now.';}}tuman_teacher_page_start('Add billing rule');?>
<h1>Add billing rule</h1><p>One fixed-monthly rule may apply at a time. You may add several hourly rules, such as R1 and R2.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=(int)$s['assignment_id']?>"><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Rule name <input name="rule_name" required placeholder="e.g. R1 or Monthly tuition" value="<?=htmlspecialchars($v['rule_name'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Billing mode <select name="billing_mode"><option value="FIXED_MONTHLY">Fixed monthly</option><option value="HOURLY" selected>Hourly</option></select></label></p><p><label>Currency <select name="currency_code"><?php foreach(TUMAN_CURRENCIES as $code=>$name):?><option value="<?=$code?>"><?=$code?></option><?php endforeach;?></select></label></p><p><label>Rate <input name="rate" required value="<?=htmlspecialchars($v['rate'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Effective from <input type="date" name="effective_from" required value="<?=htmlspecialchars($v['effective_from'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Effective to <input type="date" name="effective_to" value="<?=htmlspecialchars($v['effective_to'],ENT_QUOTES,'UTF-8')?>"></label></p><p><button>Save billing rule</button> <a href="/Tuman/teacher/billing.php">Cancel</a></p></form><?php tuman_teacher_page_end();?>
